def test_list_exadb_vm_clusters_pager(transport_name: str = "grpc"):
    client = OracleDatabaseClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(
        type(client.transport.list_exadb_vm_clusters), "__call__"
    ) as call:
        # Set the response to a series of pages.
        call.side_effect = (
            oracledatabase.ListExadbVmClustersResponse(
                exadb_vm_clusters=[
                    exadb_vm_cluster.ExadbVmCluster(),
                    exadb_vm_cluster.ExadbVmCluster(),
                    exadb_vm_cluster.ExadbVmCluster(),
                ],
                next_page_token="abc",
            ),
            oracledatabase.ListExadbVmClustersResponse(
                exadb_vm_clusters=[],
                next_page_token="def",
            ),
            oracledatabase.ListExadbVmClustersResponse(
                exadb_vm_clusters=[
                    exadb_vm_cluster.ExadbVmCluster(),
                ],
                next_page_token="ghi",
            ),
            oracledatabase.ListExadbVmClustersResponse(
                exadb_vm_clusters=[
                    exadb_vm_cluster.ExadbVmCluster(),
                    exadb_vm_cluster.ExadbVmCluster(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        expected_metadata = tuple(expected_metadata) + (
            gapic_v1.routing_header.to_grpc_metadata((("parent", ""),)),
        )
        pager = client.list_exadb_vm_clusters(request={}, retry=retry, timeout=timeout)

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(isinstance(i, exadb_vm_cluster.ExadbVmCluster) for i in results)


