def test_list_databases_pager(transport_name: str = "grpc"):
    client = OracleDatabaseClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(type(client.transport.list_databases), "__call__") as call:
        # Set the response to a series of pages.
        call.side_effect = (
            database.ListDatabasesResponse(
                databases=[
                    database.Database(),
                    database.Database(),
                    database.Database(),
                ],
                next_page_token="abc",
            ),
            database.ListDatabasesResponse(
                databases=[],
                next_page_token="def",
            ),
            database.ListDatabasesResponse(
                databases=[
                    database.Database(),
                ],
                next_page_token="ghi",
            ),
            database.ListDatabasesResponse(
                databases=[
                    database.Database(),
                    database.Database(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        expected_metadata = tuple(expected_metadata) + (
            gapic_v1.routing_header.to_grpc_metadata((("parent", ""),)),
        )
        pager = client.list_databases(request={}, retry=retry, timeout=timeout)

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(isinstance(i, database.Database) for i in results)


