def test_list_pluggable_databases_pager(transport_name: str = "grpc"):
    client = OracleDatabaseClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(
        type(client.transport.list_pluggable_databases), "__call__"
    ) as call:
        # Set the response to a series of pages.
        call.side_effect = (
            pluggable_database.ListPluggableDatabasesResponse(
                pluggable_databases=[
                    pluggable_database.PluggableDatabase(),
                    pluggable_database.PluggableDatabase(),
                    pluggable_database.PluggableDatabase(),
                ],
                next_page_token="abc",
            ),
            pluggable_database.ListPluggableDatabasesResponse(
                pluggable_databases=[],
                next_page_token="def",
            ),
            pluggable_database.ListPluggableDatabasesResponse(
                pluggable_databases=[
                    pluggable_database.PluggableDatabase(),
                ],
                next_page_token="ghi",
            ),
            pluggable_database.ListPluggableDatabasesResponse(
                pluggable_databases=[
                    pluggable_database.PluggableDatabase(),
                    pluggable_database.PluggableDatabase(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        expected_metadata = tuple(expected_metadata) + (
            gapic_v1.routing_header.to_grpc_metadata((("parent", ""),)),
        )
        pager = client.list_pluggable_databases(
            request={}, retry=retry, timeout=timeout
        )

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(isinstance(i, pluggable_database.PluggableDatabase) for i in results)


