def test_list_db_versions_pager(transport_name: str = "grpc"):
    client = OracleDatabaseClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(type(client.transport.list_db_versions), "__call__") as call:
        # Set the response to a series of pages.
        call.side_effect = (
            db_version.ListDbVersionsResponse(
                db_versions=[
                    db_version.DbVersion(),
                    db_version.DbVersion(),
                    db_version.DbVersion(),
                ],
                next_page_token="abc",
            ),
            db_version.ListDbVersionsResponse(
                db_versions=[],
                next_page_token="def",
            ),
            db_version.ListDbVersionsResponse(
                db_versions=[
                    db_version.DbVersion(),
                ],
                next_page_token="ghi",
            ),
            db_version.ListDbVersionsResponse(
                db_versions=[
                    db_version.DbVersion(),
                    db_version.DbVersion(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        expected_metadata = tuple(expected_metadata) + (
            gapic_v1.routing_header.to_grpc_metadata((("parent", ""),)),
        )
        pager = client.list_db_versions(request={}, retry=retry, timeout=timeout)

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(isinstance(i, db_version.DbVersion) for i in results)


